import{_ as o,o as r,c as a,a0 as n}from"./chunks/framework.CSK6mTG2.js";const h=JSON.parse('{"title":"数据准备与合成数据：喂给模型什么「食」","description":"","frontmatter":{"title":"数据准备与合成数据：喂给模型什么「食」","author":"唐超","date":"2026-07-27T00:00:00.000Z"},"headers":[],"relativePath":"menuAI/data-preparation-synthetic-data.md","filePath":"menuAI/data-preparation-synthetic-data.md"}'),p={name:"menuAI/data-preparation-synthetic-data.md"};function s(e,t,u,g,i,q){return r(),a("div",null,[...t[0]||(t[0]=[n('<h1 id="数据准备与合成数据-喂给模型什么「食」" tabindex="-1">数据准备与合成数据：喂给模型什么「食」 <a class="header-anchor" href="#数据准备与合成数据-喂给模型什么「食」" aria-label="Permalink to &quot;数据准备与合成数据：喂给模型什么「食」&quot;">​</a></h1><h2 id="一个容易被忽略的事实" tabindex="-1">一个容易被忽略的事实 <a class="header-anchor" href="#一个容易被忽略的事实" aria-label="Permalink to &quot;一个容易被忽略的事实&quot;">​</a></h2><p>聊微调的时候，大家的目光总是集中在算法上：LoRA 还是全量？学习率多大？训练几个 epoch？</p><p>但做过的都知道，<strong>真正决定微调效果的，80% 是数据，20% 才是算法</strong>。</p><p>打个比方：你要培养一个实习生。你的教学水平（算法）当然重要，但如果你给他的学习材料（数据）全是过时的、矛盾的、或者根本跟他的工作不相关——再怎么教也白搭。</p><p>这一篇，我们就把焦点放在数据上。高质量的微调数据从哪来？怎么整理？不够怎么办？</p><h2 id="什么样的数据是好数据" tabindex="-1">什么样的数据是好数据？ <a class="header-anchor" href="#什么样的数据是好数据" aria-label="Permalink to &quot;什么样的数据是好数据？&quot;">​</a></h2><p>先给&quot;好数据&quot;画个像：</p><p><strong>多样性要够。</strong> 如果你想让模型学会写 SQL，光给它&quot;SELECT * FROM users&quot;是不够的。它需要看到各种花样：多表 JOIN、子查询、窗口函数、不同数据库的方言、出错的 SQL 和对应的修正……记住一条经验法则：<strong>微调不是教模型&quot;记住答案&quot;，而是教它&quot;掌握模式&quot;</strong>。模式只能从多样性中来。</p><p><strong>质量要一致。</strong> 一条完美的指令 + 一条垃圾输出 = 整体质量被拉低。数据不是越多越好，100 条精心打磨的数据可能胜过 10000 条粗糙数据。想象你在教一个人做菜——给他看十道米其林级别的菜谱，比给他看一百道&quot;少许盐、适量油&quot;的模糊菜谱有用得多。</p><p><strong>格式要统一。</strong> 如果你用 JSON 格式标注对话，就全部用 JSON；如果你用 Markdown 分隔角色，就全部用 Markdown。格式不一致会让模型产生混淆——它不知道到底是该输出 JSON 还是 Markdown，最后可能输出一个诡异的混合体。</p><p><strong>覆盖要均衡。</strong> 你不能只有&quot;难&quot;的数据，也不能只有&quot;简单&quot;的数据。理想的数据分布应该像一个金字塔：大量中等难度的样本打底，配一些简单和困难的样本做边界。这跟人类学习一样——一直在舒适区学不到东西，一直在恐慌区会崩溃。</p><h2 id="数据的-三件套-指令、输入、输出" tabindex="-1">数据的&quot;三件套&quot;：指令、输入、输出 <a class="header-anchor" href="#数据的-三件套-指令、输入、输出" aria-label="Permalink to &quot;数据的&quot;三件套&quot;：指令、输入、输出&quot;">​</a></h2><p>现在主流的数据格式是 Instruction-Following 格式，结构很清晰：</p><ul><li><strong>指令（Instruction）</strong>：告诉模型要做什么。比如&quot;把下面这段话翻译成英文&quot;。</li><li><strong>输入（Input）</strong>：给模型的具体素材。比如待翻译的中文段落。</li><li><strong>输出（Output）</strong>：你期望模型给出的答案。比如翻译好的英文段落。</li></ul><p>有些任务不需要输入（比如开放式问答），那就是只有 Instruction + Output。</p><p>看上去简单？真正的坑在细节里。</p><p><strong>指令要具体，但不要啰嗦。</strong> &quot;翻译成英文&quot;太模糊——是美式英语还是英式英语？正式还是口语？好的指令应该是&quot;将以下中文翻译为美式商务英语，保持原文的正式语体&quot;。</p><p><strong>输出要高质量，而且要&quot;想得通&quot;。</strong> 如果你的数据里输出质量参差不齐，模型会学到&quot;有时候可以随便回答&quot;。另外，如果是一个推理任务，输出里最好包含推理过程（Chain-of-Thought），这样模型学到的不只是结论，还有推理方法。</p><p><strong>正负样本的比例要合理。</strong> 有些场景你需要告诉模型&quot;什么时候该拒绝&quot;。比如做一个客服机器人，你应该加入一些用户问无关问题、模型礼貌拒绝的例子。没有负样本，模型会对什么请求都试图回答。</p><h2 id="数据从哪来-五大来源" tabindex="-1">数据从哪来？五大来源 <a class="header-anchor" href="#数据从哪来-五大来源" aria-label="Permalink to &quot;数据从哪来？五大来源&quot;">​</a></h2><p>来源一：<strong>现成数据集。</strong> 开源社区已经积累了大量高质量数据集。Alpaca、ShareGPT、OpenOrca、UltraChat……这些都是经过验证的数据集。直接用、或作为种子数据再加工，是最省力的起点。</p><p>来源二：<strong>人工标注。</strong> 质量最高、成本也最高。适合核心技术场景或商业产品。找领域专家标注，一条数据可能要几十块到上百块。10000 条高质量标注数据可能要花几十万——这还只是数据成本，不算训练成本。</p><p>来源三：<strong>从用户交互中挖掘。</strong> 如果你已经有一个产品在跑，用户的真实对话就是金矿。需要注意的是用户数据涉及隐私，脱敏和合规是前提。另外用户对话往往质量参差——他们问得清楚的要保留，问得模糊的要么修正、要么丢弃。</p><p>来源四：<strong>爬取 + 清洗。</strong> 从论坛（Stack Overflow、知乎）、文档（官方 API 文档、技术手册）、问答平台收集数据。关键不是爬取，而是清洗——去重、去广告、去无意义内容、格式标准化。</p><p>来源五：<strong>合成数据。</strong> 这是近几年最火的数据获取方式，我们展开讲。</p><h2 id="合成数据-用-ai-造数据喂-ai" tabindex="-1">合成数据：用 AI 造数据喂 AI <a class="header-anchor" href="#合成数据-用-ai-造数据喂-ai" aria-label="Permalink to &quot;合成数据：用 AI 造数据喂 AI&quot;">​</a></h2><p>合成数据的思路很直接：<strong>让一个强模型（如 GPT-4、Claude）帮你生成微调数据，然后用这些数据去训练你的目标模型</strong>。</p><p>你可能会疑惑：这不就成了&quot;用 GPT-4 的数据训练自己的模型，那直接用 GPT-4 不就好了&quot;？</p><p>答案是：场景不同。GPT-4 是通用模型，又贵又慢，而且你无法控制它的私有部署。你自己的模型可以针对特定场景深度优化、可以离线部署、可以控制成本。</p><p>合成数据有几个经典套路：</p><p><strong>套路一：Self-Instruct（自我指令）。</strong> 给 GPT-4 几个示例，让它模仿着生成更多类似的任务指令。有人说&quot;这不就是套娃吗&quot;，对，本质上就是套娃——但效果出奇地好。你给它 10 个种子指令，它能生成 1000 个变体。</p><p><strong>套路二：Evol-Instruct（指令进化）。</strong> 不是从零生成，而是在已有指令的基础上做&quot;难度升级&quot;。比如把一个简单的翻译任务重写为&quot;翻译并保持原文的修辞手法&quot;；把一个数学题重写为需要多步推理的复杂版本。这样你能得到一个从简单到困难的完整数据链条。</p><p><strong>套路三：反向生成。</strong> 先写好期望的输出，让强模型反推出对应的指令。这特别适合那些&quot;你知道理想答案长什么样，但不知道怎么描述任务&quot;的场景。</p><p><strong>套路四：多轮对话构建。</strong> 模拟真实的用户-AI 交互流程。你给强模型一个角色设定（比如&quot;你是一个前端技术顾问&quot;），让它自己生成用户问题和回答。注意要加入纠错、追问、澄清这些真实对话中的常见情况。</p><h2 id="合成数据不是银弹" tabindex="-1">合成数据不是银弹 <a class="header-anchor" href="#合成数据不是银弹" aria-label="Permalink to &quot;合成数据不是银弹&quot;">​</a></h2><p>合成数据虽然好用，但有几个坑必须跳过去：</p><p><strong>模型偏差会遗传。</strong> 你用的是 GPT-4 生成的数学题，GPT-4 自己可能在某些数学类型上有系统性盲区——这些盲区会完整地遗传给你的目标模型。所以<strong>不要只用一个大模型生成所有数据</strong>，混用多个强模型可以有效减轻偏差。</p><p><strong>多样性幻觉。</strong> 强模型生成 10000 条数据，表面上每一条都不一样，但仔细看可能都是同一套思维模式的不同变体。解决方案是：在 Prompt 里显式要求多样性（&quot;请生成涵盖不同领域、不同难度、不同对话风格的任务&quot;），并且在生成后做语义聚类检查。</p><p><strong>幻觉污染。</strong> 如果强模型在生成数据时自己产生了幻觉（比如捏造了不存在的 API），这些幻觉会被当成正确答案教给你的目标模型。关键领域的合成数据必须经过人工抽检。</p><p><strong>隐私边界。</strong> 如果你的业务涉及敏感数据，不要把它们喂给 GPT-4 来生成合成数据——除非你用的是 API 的商业版（有数据不用于训练条款）。一个安全的做法是用本地部署的强模型做数据生成。</p><h2 id="实操流程-一次完整的数据准备" tabindex="-1">实操流程：一次完整的数据准备 <a class="header-anchor" href="#实操流程-一次完整的数据准备" aria-label="Permalink to &quot;实操流程：一次完整的数据准备&quot;">​</a></h2><p>想象你要微调一个前端代码审查助手。完整的数据准备流程大概是这样的：</p><p><strong>Step 1：定义数据画像。</strong> 列出你要覆盖的场景矩阵：代码风格检查、安全漏洞检测、性能优化建议、可访问性审查……每个场景大概需要多少条数据，难度分布如何。</p><p><strong>Step 2：收集种子数据（50-100 条）。</strong> 自己手写或者找团队里资深的前端写好 50-100 条高质量示例。这是整个数据池的&quot;锚点&quot;。</p><p><strong>Step 3：生成合成数据（目标 5000 条）。</strong> 把种子数据喂给 GPT-4，用 Evol-Instruct 不断扩展和变体。每条生成的数据附带一个&quot;来源标注&quot;——是种子数据、是变体、还是全新生成。</p><p><strong>Step 4：自动清洗。</strong> 用脚本做：去重（语义去重而非字符去重）、格式校验、长度过滤（太短和太长的都剔除）、语言检测（别混入其他语言）。</p><p><strong>Step 5：人工抽检（抽 5-10%）。</strong> 随机抽 250-500 条，逐条检查质量。如果合格率不到 90%，退回 Step 3 调整 Prompt 重新生成。</p><p><strong>Step 6：数据分割。</strong> 按 8:1:1 或 9:1 分成训练集、验证集、测试集。验证集和测试集<strong>绝对不能</strong>包含合成数据——必须全部是人工标注的，这样才能客观衡量模型效果。</p><h2 id="一点心态上的建议" tabindex="-1">一点心态上的建议 <a class="header-anchor" href="#一点心态上的建议" aria-label="Permalink to &quot;一点心态上的建议&quot;">​</a></h2><p>做数据准备这件事，最容易犯的错误是&quot;贪多&quot;。总觉得数据越多越好，于是花了大量时间跑脚本生成几万条数据，结果质量稀烂，训练出来效果还不如用 500 条精细数据。</p><p>记住一个不等式：<strong>10 条人的数据 &gt; 100 条优质 AI 生成数据 &gt; 10000 条低质数据。</strong></p><p>另外，数据准备不是一次性的事。第一版训练完你会发现问题——某个场景总是翻车，那就在那个场景上多补几十条数据。&quot;训练→发现问题→补数据→再训练&quot;，这才是一个健康的迭代循环。</p><p>下一篇，我们聊聊模型训练完之后怎么把它弄到各种平台上运行——模型格式转换的那些事。</p>',54)])])}const d=o(p,[["render",s]]);export{h as __pageData,d as default};
